for src, txt in gov_docs:
    all_docs.append({"source": src, "topic": "governance", "text": txt})
for src, txt in ti_docs:
    all_docs.append({"source": src, "topic": "threat_intelligence", "text": txt})

print(f"Total source documents: {len(all_docs)}")

# Chunk with 50-word window, 10-word overlap for maximum chunk count
def chunk_text(text, chunk_size=50, overlap=10):
    words = text.split()
    chunks = []
    start = 0
    while start < len(words):
        end = min(start + chunk_size, len(words))
        chunk = " ".join(words[start:end])
        if len(chunk.split()) >= 15:
            chunks.append(chunk)
        if end >= len(words):
            break
        start += chunk_size - overlap
    return chunks

all_chunks = []
for doc_idx, doc in enumerate(all_docs):
    chunks = chunk_text(doc["text"])
    for i, chunk in enumerate(chunks):
        all_chunks.append({
            "chunk_id": f"chunk_{doc_idx:05d}_{i:03d}",
            "doc_id":   f"doc_{doc_idx:05d}",
            "source":   doc["source"],
            "topic":    doc["topic"],
            "text":     chunk,
        })

print(f"Total chunks: {len(all_chunks)}")

topic_counts = Counter(c["topic"] for c in all_chunks)
for topic, count in sorted(topic_counts.items(), key=lambda x: -x[1]):
    print(f"  {topic:<30} {count:>5} chunks")

Path("data").mkdir(exist_ok=True)
with open("data/large_kb_chunks.json", "w") as f:
    json.dump(all_chunks, f, indent=2)
print(f"\nSaved to data/large_kb_chunks.json")
